    // 按分类整理的配置选项
    categorizedOptions() {
      if (!this.modInfo || !this.modInfo.configuration_options) return [];
      const result = [];
      let currentCategory = {
        name: '基本设置',
        options: []
      };

      // 确保configuration_options存在并且是数组
      const configOptions = Array.isArray(this.modInfo.configuration_options) ? this.modInfo.configuration_options : [];
