    // 添加分类和搜索过滤
    filteredCategories() {
      // 如果没有搜索查询，返回所有分类
      if (!this.searchQuery.trim()) {
        return this.categorizedOptions;
      }
      const query = this.searchQuery.trim().toLowerCase();

      // 过滤包含查询词的选项
      return this.categorizedOptions.map(category => {
        const filteredOptions = category.options.filter(option => {
          // 检查名称、标签、悬停提示
          return option.name && option.name.toLowerCase().includes(query) || option.label && option.label.toLowerCase().includes(query) || option.hover && option.hover.toLowerCase().includes(query);
