      this.dialogVisible = newVal;
      if (newVal) {
        // 在visible变为true时初始化配置，确保只会请求一次
        this.initializeConfig();
        // 打开对话框时，移除页面滚动条
        document.body.style.overflow = 'hidden';
      } else {
        // 关闭对话框时，恢复页面滚动条
        document.body.style.overflow = '';
      }
    },
    dialogVisible(newVal) {
      if (!newVal) {
        this.$emit('update:visible', false);
        // 关闭对话框时，恢复页面滚动条
        document.body.style.overflow = '';
